"""Named meters and finite ideal bus tests; no dispatch or engineering acceptance."""
from decimal import Decimal as Q
from food import q,ceil

def compute(cfg,food,water,housing,option):
 p=cfg['power'];o=p['options'][option];secondary=q(water['normal_secondary_inside_public60_GWh']) if p['public_meter_includes_calculated_secondary_sewage'] else Q(0);public=q(p['public_meter_GWh'])-secondary
 if public<0:raise ValueError('Assigned secondary meter exceeds public total')
 construction=q(housing['rebuild_events'])*q(p['rebuild_site_MWh_each'])/1000+q(housing['repair_events'])*q(p['repair_site_MWh_each'])/1000+q(housing['temporary_peak'])*q(p['temporary_home_site_MWh_each'])/1000
 meters={'occupied_homes':q(p['occupied_home_GWh']),'unoccupied_standby':q(p['unoccupied_structures'])*q(p['unoccupied_each_kWh'])/1000000,'public_nonutility_after_secondary_match':public,'food_chain':q(food['electricity_GWh']),'water_including_matched_secondary':q(water['normal_electricity_GWh']),'housing_work_sites':construction,'private_help_depot':q(p['private_help_depot_GWh']),'private_goods_retail':q(p['private_goods_retail_GWh'])};load=sum(meters.values());battery=q(o['battery_AC_MWh']);loss=battery*q(p['battery_cycles'])*(1/q(p['battery_roundtrip'])-1)/1000;injection=(load+loss)/(1-q(p['distribution_loss']));local=q(p['solar_GWh'])+q(p['wind_GWh'])+q(p['firm_scheduled_GWh']);imports=max(Q(0),injection-local);curtail=max(Q(0),local-injection);stress=max(q(p['retained_independent_bus_stress_MW']),load*1000/8760*2);hot=stress+q(p['weather_additional_MW']);firm=q(o['total_firm_units'])*25;after=firm-25;available=battery*(1-q(p['battery_operational_hold']));tests=[]
 for label,MW in [('retained_or_named_bus',stress),('weather_plus_named_bus',hot)]:
  for hours in p['test_hours']:
   deficit=max(Q(0),MW-after);tests.append({'demand_case':label,'hours':hours,'demand_MW':MW,'after_both_links_and_one_firm_lost_MW':after,'battery_available_AC_MWh_after_hold':available,'deficit_MW':deficit,'energy_need_MWh':deficit*hours,'power_bound_pass':q(o['battery_MW'])>=deficit,'energy_bound_pass':available>=deficit*hours,'ideal_static_pass':q(o['battery_MW'])>=deficit and available>=deficit*hours,'actual_charge_fuel_response_or_voltage':None})
 newunits=o['total_firm_units']-len(p['legacy_firm_ids']);firmcap=q(newunits)*q(p['new_firm_each_CU']);batterycap=q(p['strong_battery_20MW160MWh_CU'])+q(o['new_extra_battery_CU']);fuelcap=q(p['fuel_storage_stock_quote_CU']);newcap=firmcap+batterycap+fuelcap;retained=q(p['legacy_base_stock_CU']);renew=retained/q(cfg['asset_life_years']['power_base'])+firmcap/q(cfg['asset_life_years']['firm'])+batterycap/q(cfg['asset_life_years']['battery'])+fuelcap/q(cfg['asset_life_years']['fuel_storage']);crew=p['new_power_crew'];batterycrew=ceil(max(Q(0),battery-240)/160);pro=(o['total_firm_units']+crew['dispatch_posts'])*ceil(q(8760)*q('1.12')/q(cfg['continuous_task_hours']))+crew['professional_other']+batterycrew*crew['battery_extra_professional_per160MWh'];front=crew['frontline']+batterycrew*crew['battery_extra_frontline_per160MWh'];pay=q(pro)*q(cfg['pay']['professional'])+q(front)*q(cfg['pay']['frontline']);fuel=q(p['firm_scheduled_GWh'])*1000/q(p['firm_efficiency']);stockthermal=after*24*q(p['fuel_days_stock'])/q(p['firm_efficiency']);powerFU=imports*1000*q(p['import_FU_MWh'])+fuel*q(p['fuel_FU_thermal_MWh']);initialcharge=battery/q(p['battery_roundtrip'])/(1-q(p['distribution_loss']))
 parts=q(p['power_other_parts_CU'])+q(newunits)*q(p['new_firm_nonlabor_CU_each'])+batterycap*q(p['new_battery_nonlabor_fraction_capital'])
 return {'option':option,'end_use_meters_GWh':meters,'end_use_GWh':load,'secondary_public_overlap_matched_GWh':secondary,'battery_cycle_loss_enduse_GWh':loss,'grid_injection_GWh':injection,'annual_local_hypothesis_GWh':local,'annual_import_GWh':imports,'curtailed_hypothesis_GWh':curtail,'annual_import_offer_volume_pass':imports<=q(p['annual_import_quote_GWh']),'firm_unit_ids':p['legacy_firm_ids']+list('CDEFG')[:newunits],'new_firm_unit_ids':list('CDEFG')[:newunits],'battery_MW':o['battery_MW'],'battery_AC_MWh':battery,'battery_operational_hold_AC_MWh':battery-available,'retained_stress_MW':stress,'weather_stress_MW':hot,'tests':tests,'instantaneous_two_link_step_ideal_power_bound_pass':q(o['battery_MW'])>=q(p['both_link_step_MW']),'retained_assets_CU':retained,'new_power_construction_CU':newcap,'total_asset_quote_CU':retained+newcap,'renewal_CU':renew,'professional_people':pro,'frontline_people':front,'pay_CU':pay,'other_parts_CU':parts,'parts_import_FU':parts*q(p['parts_import_fraction'])/q(cfg['CU_per_FU']),'normal_power_and_fuel_FU':powerFU,'scheduled_fuel_thermal_MWh':fuel,'scheduled_fuel_CO2_t':fuel*q(p['fuel_CO2_t_MWh_thermal']),'initial_fuel_stock_thermal_MWh':stockthermal,'initial_fuel_stock_FU':stockthermal*q(p['fuel_FU_thermal_MWh']),'initial_battery_charge_grid_MWh':initialcharge,'initial_battery_charge_FU':initialcharge*q(p['import_FU_MWh']),'new_asset_import_FU':firmcap*q(cfg['asset_import_fraction']['power_firm'])+batterycap*q(cfg['asset_import_fraction']['power_battery'])+fuelcap*q('.5'),'actual_largest_contingency_dispatch_source_or_fuel_acceptance':None}
